class Solution {
public:
    int minAdjacentSwaps(vector<int>& nums,int a,int b){
        const long long MOD=1000000007;
        long long seenMid=0,seenHigh=0,ans=0;
        for(int x:nums){
            if(x<a)ans+=seenMid+seenHigh;
            else if(x<=b){ans+=seenHigh;++seenMid;}
            else ++seenHigh;
        }
        return (int)(ans%MOD);
    }
};
